using System;using System.Collections;using System.Collections.Generic;using System.Reflection;using System.IO;using UnityEngine;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;using EchoProtocol.Player;using EchoProtocol.Echo;using EchoProtocol.Horror;
public sealed class FreshR3Probe:MonoBehaviour{
 FirstPersonController player;VS1HubReturnGate gate;Keyboard keyboard;Mouse mouse;Key[] keys=Array.Empty<Key>();float yaw;bool running;
 public static void Run(){var g=new GameObject("Temporary Fresh R3 actor tests");g.AddComponent<FreshR3Probe>().StartCoroutine(g.GetComponent<FreshR3Probe>().Test());}
 void Feed(){if(!running||InputState.currentUpdateType!=InputUpdateType.Dynamic)return;InputSystem.QueueStateEvent(keyboard,new KeyboardState(keys));InputSystem.QueueStateEvent(mouse,new MouseState{delta=new Vector2(Mathf.Clamp(Mathf.DeltaAngle(player.transform.eulerAngles.y,yaw),-12,12)/.15f,0)});typeof(FirstPersonController).GetField("cursorIsLocked",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(player,true);}
 IEnumerator Face(float y){yaw=y;keys=Array.Empty<Key>();while(Mathf.Abs(Mathf.DeltaAngle(player.transform.eulerAngles.y,yaw))>1)yield return null;yield return new WaitForSeconds(.1f);}
 IEnumerator Go(float x,float z,float y){yield return Face(y);float start=Time.time;while(Vector2.Distance(new Vector2(player.transform.position.x,player.transform.position.z),new Vector2(x,z))>.1f){if(Time.time-start>12)throw new Exception("Fresh route blocked unexpectedly");var d=player.transform.InverseTransformDirection(new Vector3(x,player.transform.position.y,z)-player.transform.position);var k=new List<Key>();if(d.x>.065f)k.Add(Key.D);else if(d.x<-.065f)k.Add(Key.A);if(d.z>.065f)k.Add(Key.W);else if(d.z<-.065f)k.Add(Key.S);keys=k.ToArray();yield return null;}keys=Array.Empty<Key>();yield return new WaitForSeconds(.1f);}
 void C(bool b,string s){File.AppendAllText("/tmp/echo-vs1-r3/fresh-physical.txt",(b?"PASS ":"FAIL ")+s+"\n");if(!b)throw new Exception(s);}
 IEnumerator Test(){player=FindFirstObjectByType<FirstPersonController>();gate=FindFirstObjectByType<VS1HubReturnGate>();keyboard=InputSystem.AddDevice<Keyboard>();mouse=InputSystem.AddDevice<Mouse>();var pi=player.GetComponent<PlayerInput>();pi.neverAutoSwitchControlSchemes=true;pi.SwitchCurrentControlScheme("Keyboard&Mouse",keyboard,mouse);pi.ActivateInput();InputSystem.settings.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;InputSystem.onBeforeUpdate+=Feed;running=true;File.WriteAllText("/tmp/echo-vs1-r3/fresh-physical.txt","");
 yield return Go(-3.5f,-9.5f,270);keys=new[]{Key.W};yield return new WaitForSeconds(1);keys=Array.Empty<Key>();C(player.transform.position.x>-4.8f&&!gate.IsOpen,"fresh real Player blocked by original-Hub exit leaf");
 yield return Go(-2.75f,-6,0);yield return Go(-2.75f,15.3f,0);keys=new[]{Key.W};yield return new WaitForSeconds(1);keys=Array.Empty<Key>();C(player.transform.position.z<16&&!gate.IsOpen,"fresh real Player cannot bypass P1 via glass lane north boundary");C(FindFirstObjectByType<LoopController>().CheckpointRevision==0,"fresh session retains original checkpoint baseline");running=false;InputSystem.QueueStateEvent(keyboard,new KeyboardState());}
 void OnDestroy(){running=false;InputSystem.onBeforeUpdate-=Feed;if(keyboard!=null&&keyboard.added)InputSystem.RemoveDevice(keyboard);if(mouse!=null&&mouse.added)InputSystem.RemoveDevice(mouse);}
}
#endif
